/** True when a continuous road (4-neighbour) has tiles on both plot `a` and plot `b`. */
export function plotsLinkedByRoad(city: CityState, lookup: ItemLookup, a = 0, b = 1): boolean {
  if (city.plots <= Math.max(a, b)) return false;
  const roads = new Set<string>();
  for (const placed of city.items) {
    if (lookup(placed.itemId)?.kind === 'road') roads.add(tileKey(placed.x, placed.y));
  }
  const visited = new Set<string>();
  for (const start of roads) {
    if (visited.has(start)) continue;
    let touchesA = false;
    let touchesB = false;
    const queue = [start];
    visited.add(start);
    while (queue.length > 0) {
      const key = queue.pop() as string;
      const [xs, ys] = key.split(',');
      const x = Number(xs);
      const y = Number(ys);
      const plot = plotAt(x, y, city.plots);
      if (plot === a) touchesA = true;
      if (plot === b) touchesB = true;
      for (const next of [
        tileKey(x + 1, y),
        tileKey(x - 1, y),
        tileKey(x, y + 1),
        tileKey(x, y - 1),
      ]) {
        if (roads.has(next) && !visited.has(next)) {
          visited.add(next);
          queue.push(next);
        }
      }
    }
    if (touchesA && touchesB) return true;
  }
  return false;
}
